"""
    Compare two configurations. They are considered equal if they hold the same values for all keys.
    :param configuration1: the first configuration in the comparison
    :param configuration2: the second configuration in the comparison
    :param keys: the keys to use for comparison
    :return: boolean indicating if configurations are equal or not
    """
def are_configurations_equal(
    configuration1: Any, configuration2: Any, keys: Any
) -> object {
    for key in keys {
        if (configuration1[key] != configuration2[key]) {
            return False;
        }
    }
    return True;
}

test_blocks:
test "t0" {
    assert (
        are_configurations_equal({'a': 1, 'b': 2}, {'a': 1, 'b': 2}, ('a', 'b')) == True
    );;
}

test "t1" {
    assert (
        are_configurations_equal({'a': 1, 'b': 2}, {'a': 1, 'b': 3}, ('a', )) == True
    );;
}

test "t2" {
    assert (
        are_configurations_equal(
            {"a": "b", "b": "c", "c": "d"},
            {"a": "b", "b": "c", "c": "d"},
            ["a", "b", "c"]
        )
        == True
    );;
}

test "t3" {
    assert (
        are_configurations_equal(
            {'a': 1, 'b': 2, 'c': 3, 'd': 4},
            {'a': 1, 'b': 2, 'c': 3, 'd': 4},
            ['a', 'b', 'c']
        )
        == True
    );;
}

test "t4" {
    assert (
        are_configurations_equal(
            {"a": "b", "b": "c", "c": "d"},
            {"a": "b", "b": "c", "c": "e"},
            ["a", "b", "c"]
        )
        == False
    );;
}

test "t5" {
    assert (
        are_configurations_equal({'a': 1, 'b': 2}, {'a': 1, 'b': 3}, ('a', 'b'))
        == False
    );;
}

test "t6" {
    assert (
        are_configurations_equal(
            {'a': 1, 'b': 2, 'c': 3}, {'a': 1, 'b': 3, 'c': 3}, ['a', 'b', 'c']
        )
        == False
    );;
}

test "t7" {
    assert (
        are_configurations_equal(
            {'a': 1, 'b': 2, 'c': 3}, {'a': 1, 'b': 2, 'c': 4}, ['a', 'b', 'c']
        )
        == False
    );;
}

test "t8" {
    assert (
        are_configurations_equal(
            {'a': 1, 'b': 2, 'c': 3}, {'a': 1, 'b': 2, 'c': 3}, ['a', 'b', 'c']
        )
        == True
    );;
}
